ee:variables.ee:set-variable:
%dw 2.0
import substringBefore from dw::core::Strings
output application/json
var direccion = if(vars.orderResponseIDP.direccionDespachar != "0")
					if (lower(vars.orderResponseIDP.direccionDespachar) == "bodega central") "CM11"
					else if (vars.orderResponseIDP.direccionDespachar contains " ") (substringBefore(vars.orderResponseIDP.direccionDespachar," "))
					else (vars.orderResponseIDP.direccionDespachar)
				else "NO ENCONTRADO"
---
"SELECT Id, Cod_Cliente__c, Global_regi_n__c FROM Tiernda_Obra__c WHERE Name LIKE '%" ++ direccion ++ "%' AND Cuenta__c = '" ++ (vars.solicitante[0].Id default "") ++ "' AND Cod_Cliente__c <> null AND IsDeleted=false ORDER BY LastModifiedDate DESC"

%dw 2.0
output application/json
var pricebookId = p('secure::Salesforce.datosFijos.pricebook2Id')
var productoId = vars.producto[0].Id default p('secure::Salesforce.datosFijos.productoNoEncontrado')
---
"SELECT Id FROM PricebookEntry WHERE Pricebook2Id='" ++ pricebookId ++ "' AND Product2Id='" ++ productoId ++ "' AND CurrencyIsoCode='CLP'"

%dw 2.0
output application/json
var pricebookId = p('secure::Salesforce.datosFijos.pricebook2Id')
var productoFleteId = vars.productoFlete[0].Id default p('secure::Salesforce.datosFijos.productoNoEncontrado')
---
"SELECT Id FROM PricebookEntry WHERE Pricebook2Id='" ++ pricebookId ++ "' AND Product2Id='" ++ productoFleteId ++ "' AND CurrencyIsoCode='CLP'"

%dw 2.0
output application/java
---
vars.orderProductArray ++ vars.orderFleteArray
	map ((item, index) -> 
        item update {
            case .VM_Item__c -> ((index + 1) * 10) as String {format: "000000"}
        }
    )
